#include "stdlib/stats/base/dists/lognormal/cdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/assert/is_infinitef.h"
#include "stdlib/math/base/assert/is_nonpositive_finite.h"
#include "stdlib/math/base/special/erf.h"
#include "stdlib/math/base/special/ln.h"
#include "stdlib/math/base/special/sqrt.h"


/**
* Returns the expected value for a lognormal distribution with location `mu` and scale `sigma`.
*
* @param x      input value
* @param mu     location parameter
* @param sigma  scale parameter
* @return       expected value
*
* @example
* double y = stdlib_base_dists_lognormal_cdf( 2.0, 0.0, 1.0 );
* // returns ~0.756
*/
double stdlib_base_dists_lognormal_cdf( const double x, const double mu, const double sigma ) {
    if ( stdlib_base_is_nan( x ) || 
         stdlib_base_is_nan( mu ) || 
         stdlib_base_is_nan( sigma ) || 
         sigma <= 0.0 || 
         stdlib_base_is_infinitef( sigma ) ) {
        return 0.0 / 0.0; // NaN
    }
    if ( stdlib_base_is_infinitef( x ) ) {
        return ( x > 0.0 ) ? 1.0 : 0.0; // +infinity -> 1, -infinity -> 0
    }
    if ( x < 0.0 ) {
        return 0.0;
    }
    if ( sigma <= 0.0 ) {
        return 0.0 / 0.0; // NaN
    }
    return ( 0.5 + ( 0.5 * stdlib_base_erf( 
        ( stdlib_base_ln( x ) - mu ) / 
        ( stdlib_base_sqrt( 2.0 ) * sigma ) 
    ) ) );
}

